function artifact=runV4BCalibrationRound1()
root=v4SetupPaths();c=sf12NoLdroSf11FlowConfig();base=v4DefaultBParameters();base.candidateIndex=0;decision=[1.01 1.10 1.20 1.50];residual=[1.01 1.05];innovation=[0.50 0.75];margin=[0 0.10];candidates=repmat(base,32,1);row=0;for a=1:4,for b=1:2,for d=1:2,for e=1:2,row=row+1;candidates(row)=base;candidates(row).decisionPeakRatioThreshold=decision(a);candidates(row).residualPeakRatioThreshold=residual(b);candidates(row).innovationLimitBins=innovation(d);candidates(row).softHammingMarginRatio=margin(e);candidates(row).candidateIndex=row;end,end,end,end
schedule=v4ContinuousPassSchedule(c);eligible=find(schedule.metricEligible);neg=eligible(schedule.frameCenterTimeSec(eligible)<0);pos=eligible(schedule.frameCenterTimeSec(eligible)>0);target=sort([neg(1:8);neg(end-7:end);pos(1:8);pos(end-7:end)]);records=repmat(struct('candidateIndex',0,'frames',32,'vpAccepted',0,'vpFalse',0,'falseAcceptance',NaN,'coverage',0,'cfoRmseBins',Inf,'halfBinExceedance',0,'passed',false),32,1);
for candidateIndex=1:32
    p=candidates(candidateIndex);state=struct('time',schedule.passStartTimeSec,'phase',0,'cross',struct());accepted=0;falseVp=0;sse=0;count=0;exceed=0;
    for fi=1:schedule.frameCount,ledger=v4RandomLedger(c,'validation',9,1,fi);frame=v4GenerateContinuousFrame(c,state.time,-21,ledger,state.phase,'AWGN');state.time=frame.nextFrameStartTimeSec;state.phase=frame.nextFrameStartPhaseRad;if ~schedule.metricEligible(fi),state.cross=struct();continue,end;b=v4CommonBootstrap(frame.observation.rxPhysical(1:8,:),c,SearchStepBins=p.searchStepBins);robust=v4BIndividualPreambleRate(frame.observation.rxPhysical(1:8,:),c,p.searchStepBins);measurement=schedule.frameStartTimeSec(fi)+4*c.symbolDurationSec;[rate,state.cross]=v4CrossFrameRateUpdate(state.cross,measurement,mean(b.cfoBins),robust.rateBinsPerSec,c,p);if ~ismember(fi,target),continue,end;rx=v4Stage55Decode(frame.observation,b,c,p,CrossFrameRateBinsPerSec=rate,CrossFrameHistoryCount=state.cross.historyCount);m=v4EvaluateFrame(rx,frame.truth,c);aMask=rx.virtualPilotAccepted;accepted=accepted+sum(aMask);falseVp=falseVp+sum(aMask&rx.detectedPhysicalBins~=frame.truth.payloadPhysicalBins);err=rx.estimatedCfoBins-frame.truth.dataCfoBins;sse=sse+sum(err.^2);count=count+numel(err);exceed=exceed+sum(abs(err)>=0.5);end
    if accepted>0,fa=falseVp/accepted;else,fa=NaN;end;coverage=accepted/(32*112);passed=isfinite(fa)&&fa<=0.02&&coverage>=0.01;records(candidateIndex)=struct('candidateIndex',candidateIndex,'frames',32,'vpAccepted',accepted,'vpFalse',falseVp,'falseAcceptance',fa,'coverage',coverage,'cfoRmseBins',sqrt(sse/count),'halfBinExceedance',exceed/count,'passed',passed);fprintf('B calibration candidate %d/32 accepted=%d false=%d coverage=%.4f rmse=%.4f\n',candidateIndex,accepted,falseVp,coverage,sqrt(sse/count));
end
valid=find([records.passed]);if isempty(valid),selected=NaN;else,score=[-[records(valid).coverage].' [records(valid).cfoRmseBins].' valid];[~,order]=sortrows(score,[1 2 3]);selected=valid(order(1));end;artifact=struct('status',ternary(isfinite(selected),'PASS','FAIL'),'algorithmVersion','Stage55-B-project-path-calibrated-v7','candidateCount',32,'calibrationFramesPerCandidate',32,'selectedCandidateIndex',selected,'records',records,'selectionUsesSerOrBer',false,'parameters',pick(candidates,selected),'conditionsFrozen',true);folder=fullfile(root,'results','calibration','track_b','B-param-v01');if ~isfolder(folder),mkdir(folder);end;save(fullfile(folder,'calibration.mat'),'artifact','-v7.3');write(fullfile(folder,'calibration.json'),jsonencode(artifact,'PrettyPrint',true));if ~isfinite(selected),error('V4:BCalibration','No B candidate met quality gate.');end
end
function x=ternary(ok,a,b),if ok,x=a;else,x=b;end,end
function x=pick(c,i),if isfinite(i),x=c(i);else,x=struct();end,end
function write(path,text),f=fopen(path,'w','n','UTF-8');cl=onCleanup(@()fclose(f));fprintf(f,'%s\n',text);clear cl,end
